package com.metrics.warmup.controller;

import org.springframework.batch.core.JobExecution;
import org.springframework.batch.core.explore.JobExplorer;
import org.springframework.batch.core.launch.JobOperator;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/batch/cache-warmup")
public class BatchWarmupController {

    private final JobOperator jobOperator;
    private final JobExplorer jobExplorer;

    public BatchWarmupController(JobOperator jobOperator, JobExplorer jobExplorer) {
        this.jobOperator = jobOperator;
        this.jobExplorer = jobExplorer;
    }

    @PostMapping("/{executionId}/stop")
    public ResponseEntity<String> stopWarmupJob(
            @PathVariable Long executionId,
            Authentication authentication) throws Exception {
        JobExecution execution = jobExplorer.getJobExecution(executionId);
        if (execution == null) {
            return ResponseEntity.notFound().build();
        }
        String tenantId = execution.getJobParameters().getString("tenantId");
        if (tenantId == null || !tenantId.equals(authentication.getName())) {
            throw new AccessDeniedException("Caller is not authorized to terminate cache warmup for this tenant");
        }
        jobOperator.stop(executionId);
        return ResponseEntity.ok("Warmup job stopped");
    }
}
